1	import type { FileMap } from "./agent";
2	
3	// The starter every new project begins from — a real Vite + React + TS +
4	// Tailwind app, not a blank page. The agent edits these files; it never
5	// chooses or installs dependencies itself (see lib/build-site.ts) — package.json
6	// here is the ONLY dependency set that will ever exist, which is what keeps
7	// the server-side build safe to run without per-generation `npm install`.
8	export const FOUNDATION_FILES: FileMap = {
9	  "package.json": JSON.stringify(
10	    {
11	      name: "kodely-site",
12	      private: true,
13	      version: "0.0.0",
14	      type: "module",
15	      scripts: { build: "vite build" },
16	      dependencies: {
17	        react: "^19.2.8",
18	        "react-dom": "^19.2.8",
19	      },
20	      devDependencies: {
21	        "@tailwindcss/vite": "^4.3.3",
22	        "@vitejs/plugin-react": "^6.0.5",
23	        tailwindcss: "^4.3.3",
24	        typescript: "^7.0.2",
25	        vite: "^8.2.1",
26	      },
27	    },
28	    null,
29	    2,
30	  ),
31	
32	  // MULTI-PAGE lives here, and it has to, because this file is the one place
33	  // the agent cannot reach: vite.config.* is on isProtectedPath in lib/agent.ts
34	  // (a config file is code we execute server-side, not data we serve). So the
35	  // build cannot take a list of pages from the model — it DISCOVERS them, by
36	  // scanning the project for .html files and making each one a Rollup entry.
37	  // Adding a page is then "write about.html", with no config edit anywhere.
38	  //
39	  // Every shell points at the SAME /src/main.tsx on purpose. One shared entry
40	  // module means Rollup emits ONE js chunk that all pages reference, rather
41	  // than a chunk per page plus a shared chunk pulled in by a bare `import`.
42	  // That matters twice over: navigating between pages reuses an already-cached
43	  // bundle, and the editor's preview (app/projects/[id]/preview-agent.ts) can
44	  // still inline the whole thing into a srcdoc document, which it cannot do
45	  // with a chunk that imports a sibling by relative URL.
46	  "vite.config.ts": `import { defineConfig } from "vite";
47	import react from "@vitejs/plugin-react";
48	import tailwindcss from "@tailwindcss/vite";
49	import { readdirSync } from "node:fs";
50	import { resolve, relative } from "node:path";
51	
52	// Never entries, and never worth walking into.
53	const SKIP = new Set(["node_modules", "dist", "src", "public"]);
54	
55	/** Every .html file under the project root, as { "about": "/abs/about.html" }. */
56	function htmlEntries(dir: string, root: string, depth = 0): Record<string, string> {
57	  const out: Record<string, string> = {};
58	  if (depth > 4) return out; // a site is not nested deeper than this
59	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
60	    if (entry.name.startsWith(".") || SKIP.has(entry.name)) continue;
61	    const full = resolve(dir, entry.name);
62	    if (entry.isDirectory()) Object.assign(out, htmlEntries(full, root, depth + 1));
63	    else if (entry.name.toLowerCase().endsWith(".html")) {
64	      const name = relative(root, full).replace(/\\\\/g, "/").replace(/\\.html$/i, "");
65	      out[name] = full;
66	    }
67	  }
68	  return out;
69	}
70	
71	// build-site.ts spawns vite with cwd set to the project, so this is the root.
72	const root = process.cwd();
73	const found = htmlEntries(root, root);
74	const input = Object.keys(found).length ? found : { index: resolve(root, "index.html") };
75	
76	export default defineConfig({
77	  plugins: [react(), tailwindcss()],
78	  build: { outDir: "dist", rollupOptions: { input } },
79	});
80	`,
