86	        useDefineForClassFields: true,
87	        lib: ["ES2022", "DOM", "DOM.Iterable"],
88	        module: "ESNext",
89	        skipLibCheck: true,
90	        moduleResolution: "bundler",
91	        allowImportingTsExtensions: true,
92	        resolveJsonModule: true,
93	        isolatedModules: true,
94	        noEmit: true,
95	        jsx: "react-jsx",
