135	  "src/main.tsx": `import { StrictMode } from "react";
136	import { createRoot } from "react-dom/client";
137	import App from "./App";
138	import "./index.css";
139	
140	const root = document.getElementById("root")!;
141	
142	createRoot(root).render(
143	  <StrictMode>
144	    <App page={root.dataset.page ?? "/"} />
145	  </StrictMode>,
146	);
147	`,
148	
149	  "src/index.css": `@import "tailwindcss";
150	
151	:root {
152	  color-scheme: light dark;
153	}
154	`,
