156	  // THE ROUTING PRIMITIVE. There is no router package and there never will be
157	  // — lib/build-site.ts symlinks one shared, pre-installed dependency tree and
158	  // never runs `npm install`, so react and react-dom are the whole universe.
159	  // This is ~40 lines of hand-rolled resolution instead, and it does less than
160	  // a router on purpose: navigation between pages is an ordinary <a href>, a
161	  // real document load of a real URL. No pushState, no history interception,
162	  // nothing that has to be re-implemented correctly for the back button.
163	  "src/router.tsx": `import type { AnchorHTMLAttributes, ComponentType } from "react";
164	import { PAGES } from "./pages";
165	
166	export type PageDef = {
167	  /** Root-relative address: "/" for the home page, "/about", "/services/boilers". */
168	  path: string;
169	  /** Text for the nav link. */
170	  label: string;
171	  component: ComponentType;
172	  /** false to keep it out of the nav (a legal page, a landing page). */
173	  nav?: boolean;
174	};
175	
176	const home = (): PageDef => PAGES.find((p) => p.path === "/") ?? PAGES[0];
177	
178	/** Normalise "about", "/about/", "/about" to "/about"; anything empty to "/". */
179	function tidy(path: string): string {
180	  const p = path.trim().replace(/^\\/+/, "").replace(/\\/+$/, "");
181	  return p ? \`/\${p}\` : "/";
182	}
183	
184	/** The page this document declares via data-page on #root. */
185	export function resolvePage(path: string): PageDef {
186	  const want = tidy(path).toLowerCase();
187	  return PAGES.find((p) => tidy(p.path).toLowerCase() === want) ?? home();
188	}
189	
190	/** Which page is on screen, for active-link styling. */
191	export function currentPath(): string {
192	  if (typeof document === "undefined") return "/";
193	  return tidy(document.getElementById("root")?.dataset.page ?? "/");
194	}
195	
196	// WHERE THE SITE IS MOUNTED. A published site sits at the root of
197	// <slug>.kodely.site, but the same files are also served under
198	// /api/site/<slug>/ on staging, so a hardcoded href="/about" is wrong half the
199	// time. The prefix is whatever precedes this document's own declared path in
200	// the URL bar, which is exact rather than guessed — and "" when there is no
201	// real URL at all (the editor preview runs from about:srcdoc).
202	let prefix: string | null = null;
203	
204	function mountPrefix(): string {
205	  if (prefix !== null) return prefix;
206	  prefix = "";
207	  if (typeof location === "undefined" || !location.pathname.startsWith("/")) return prefix;
208	  let here = location.pathname.replace(/\\.html?$/i, "").replace(/(^|\\/)index$/i, "$1");
209	  here = here.replace(/\\/+$/, "");
210	  const own = currentPath() === "/" ? "" : currentPath();
211	  if (own && here.toLowerCase().endsWith(own.toLowerCase())) here = here.slice(0, -own.length);
212	  prefix = here.replace(/\\/+$/, "");
213	  return prefix;
214	}
215	
216	/** The href a page should be linked by, valid wherever the site is mounted. */
217	export function href(path: string): string {
218	  const p = tidy(path);
219	  const base = mountPrefix();
220	  if (!base) return p;
221	  return p === "/" ? \`\${base}/\` : \`\${base}\${p}\`;
222	}
223	
224	/** Pages that belong in the nav, in table order. */
225	export function navPages(): PageDef[] {
226	  return PAGES.filter((p) => p.nav !== false);
227	}
228	
229	type LinkProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> & { to: string };
230	
231	/** An internal link. Use this instead of a bare <a href> for site pages. */
232	export function Link({ to, ...props }: LinkProps) {
233	  const target = tidy(to);
234	  return (
235	    <a
236	      href={href(target)}
237	      aria-current={target.toLowerCase() === currentPath().toLowerCase() ? "page" : undefined}
238	      {...props}
239	    />
240	  );
241	}
242	`,
243	
244	  // THE PAGE TABLE — the one file that has to change when a page is added, and
245	  // the thing the nav and the router both read. Kept apart from router.tsx so
246	  // the mechanism stays untouched while the list of pages grows.
247	  "src/pages.tsx": `import type { PageDef } from "./router";
248	import Home from "./pages/Home";
249	
250	// Adding a page takes three steps and no config change:
251	//
252	//   1. src/pages/About.tsx — the page component.
253	//   2. An entry below, in the order it should appear in the nav.
254	//   3. about.html at the project root — a copy of index.html with its OWN
255	//      <title>, <meta name="description"> and OG tags, and data-page="/about"
256	//      on the root div. That file is why /about is a separate document a
257	//      search engine can rank on its own; without it the page is unreachable.
258	//
259	// Nested pages work the same way: services/boilers.html with
260	// data-page="/services/boilers".
261	export const PAGES: PageDef[] = [
262	  { path: "/", label: "Home", component: Home },
263	];
264	`,
265	
266	  // The shell every page renders inside: chrome that is shared (nav, footer)
267	  // wraps the one page component the document asked for.
268	  "src/App.tsx": `import { resolvePage } from "./router";
269	import { SiteNav } from "./components/SiteNav";
270	
271	export default function App({ page }: { page: string }) {
272	  const Page = resolvePage(page).component;
273	
274	  return (
275	    <div className="min-h-screen bg-white text-neutral-900">
276	      <SiteNav />
277	      <main>
278	        <Page />
279	      </main>
280	    </div>
281	  );
282	}
283	`,
284	
285	  "src/pages/Home.tsx": `import { Section } from "../components/ui/Section";
286	import { Button } from "../components/ui/Button";
287	
288	export default function Home() {
289	  return (
290	    <Section>
291	      <h1 className="text-4xl font-bold tracking-tight text-neutral-900">Welcome</h1>
292	      <p className="mt-4 text-lg text-neutral-600">
293	        Describe what you want built, and I'll take it from here.
294	      </p>
295	      <Button className="mt-6">Get started</Button>
296	    </Section>
297	  );
298	}
299	`,
300	
301	  // Site-level composition rather than a primitive: it reads the page table, so
302	  // a page added there appears in the nav on every page without a second edit.
303	  // Restyle it freely — the only part that must survive is that the links come
304	  // from navPages() and go through <Link>.
305	  "src/components/SiteNav.tsx": `import { Nav } from "./ui/Nav";
306	import { Link, navPages } from "../router";
307	
308	export function SiteNav() {
309	  const pages = navPages();
310	  if (pages.length < 2) return null; // a one-page site does not need a nav
311	
312	  return (
313	    <Nav>
314	      <div className="mx-auto flex max-w-5xl items-center gap-6 px-6 py-4 text-sm">
315	        {pages.map((page) => (
316	          <Link
317	            key={page.path}
318	            to={page.path}
319	            className="rounded text-neutral-600 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-900 aria-[current=page]:font-semibold aria-[current=page]:text-neutral-900"
320	          >
321	            {page.label}
322	          </Link>
323	        ))}
324	      </div>
325	    </Nav>
326	  );
327	}
328	`,
329	
330	  "src/components/ui/Button.tsx": `import { forwardRef, type ButtonHTMLAttributes } from "react";
331	
332	type Variant = "primary" | "secondary" | "ghost";
333	
334	const variants: Record<Variant, string> = {
335	  primary: "bg-neutral-900 text-white hover:bg-neutral-800",
336	  secondary: "bg-neutral-100 text-neutral-900 hover:bg-neutral-200",
337	  ghost: "text-neutral-900 hover:bg-neutral-100",
338	};
339	
340	type Props = ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant };
341	
342	export const Button = forwardRef<HTMLButtonElement, Props>(function Button(
343	  { variant = "primary", className = "", ...props },
344	  ref,
345	) {
346	  return (
347	    <button
348	      ref={ref}
349	      className={\`inline-flex items-center justify-center rounded-lg px-4 py-2.5 text-sm font-medium transition-colors \${variants[variant]} \${className}\`}
350	      {...props}
351	    />
352	  );
353	});
354	`,
355	
356	  "src/components/ui/Card.tsx": `import type { HTMLAttributes } from "react";
357	
358	export function Card({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) {
359	  return (
360	    <div
361	      className={\`rounded-2xl border border-neutral-200 bg-white p-6 shadow-sm \${className}\`}
362	      {...props}
363	    />
364	  );
365	}
366	`,
367	
368	  "src/components/ui/Section.tsx": `import type { HTMLAttributes } from "react";
369	
370	export function Section({ className = "", ...props }: HTMLAttributes<HTMLElement>) {
371	  return <section className={\`mx-auto max-w-5xl px-6 py-16 \${className}\`} {...props} />;
372	}
373	`,
374	
375	  "src/components/ui/Nav.tsx": `import type { HTMLAttributes } from "react";
376	
377	export function Nav({ className = "", ...props }: HTMLAttributes<HTMLElement>) {
378	  return (
379	    <nav
380	      className={\`sticky top-0 z-10 border-b border-neutral-200 bg-white/80 backdrop-blur \${className}\`}
381	      {...props}
382	    />
383	  );
384	}
385	`,
386	};
