1	import { spawn } from "node:child_process";
2	import { mkdtemp, writeFile, mkdir, rm, readdir, readFile, stat, symlink } from "node:fs/promises";
3	import { tmpdir } from "node:os";
4	import { join, dirname } from "node:path";
5	import type { FileMap } from "./agent";
6	
7	// Where the foundation's dependencies are installed ONCE (see
8	// scripts/install-foundation.mjs) — every build reuses this via a symlink
9	// instead of running `npm install` per generation. The agent never chooses
10	// or adds dependencies (see lib/foundation.ts), so this is always installing
11	// exactly the same known-safe package.json, never anything request-controlled.
12	const FOUNDATION_DIR = process.env.KODELY_FOUNDATION_DIR ?? "/home/kodely/kodely-foundation";
13	
14	const BUILD_TIMEOUT_MS = 60_000;
15	
16	export class BuildError extends Error {}
17	
18	/**
19	 * Compiles a project's source files into static output via `vite build`,
20	 * in a throwaway directory, bounded by a timeout. Never runs `npm install`
21	 * — the node_modules symlink points at the one shared, pre-installed
22	 * foundation tree, so this only ever executes vite/esbuild against files
23	 * we already trust the shape of, never arbitrary installed code.
24	 */
25	export async function buildSite(sourceFiles: FileMap): Promise<FileMap> {
26	  const workDir = await mkdtemp(join(tmpdir(), "kodely-build-"));
27	
28	  try {
29	    for (const [path, content] of Object.entries(sourceFiles)) {
30	      const fullPath = join(workDir, path);
31	      await mkdir(dirname(fullPath), { recursive: true });
32	      await writeFile(fullPath, content, "utf8");
33	    }
34	
35	    // "junction" on Windows, "dir" elsewhere. A Windows directory symlink
36	    // needs SeCreateSymbolicLinkPrivilege (admin, or Developer Mode) and
37	    // otherwise fails with EPERM, which blocked every local build on a dev
38	    // machine. An NTFS junction is equivalent for this purpose and needs no
39	    // elevation; it only works for absolute local paths, which is what this
40	    // is. No behaviour change on Linux.
41	    await symlink(
42	      join(FOUNDATION_DIR, "node_modules"),
43	      join(workDir, "node_modules"),
44	      process.platform === "win32" ? "junction" : "dir",
45	    );
46	
47	    // Invoke Vite's JS entrypoint with this process's own node binary rather
48	    // than the `.bin/vite` shim: the shim is extensionless on POSIX but a
49	    // .CMD on Windows, and Node refuses to spawn .cmd without a shell. Going
50	    // straight to the entrypoint is a single code path on both platforms and
51	    // avoids shell quoting entirely.
52	    await runBounded(
53	      process.execPath,
54	      [join("node_modules", "vite", "bin", "vite.js"), "build"],
55	      workDir,
56	    );
57	
58	    return await readDistTree(join(workDir, "dist"));
59	  } finally {
60	    await rm(workDir, { recursive: true, force: true }).catch(() => {});
61	  }
62	}
63	
64	function runBounded(command: string, args: string[], cwd: string): Promise<void> {
65	  return new Promise((resolve, reject) => {
66	    // A MINIMAL environment, not the parent's.
67	    //
68	    // vite executes the project's own config and any plugin code in this child
69	    // process. Inheriting `process.env` handed that code DATABASE_URL, the
70	    // Anthropic/OAuth tokens, the session secret and the Stripe keys — so a
71	    // single successful write to a config file would have been enough to
72	    // exfiltrate every credential the app holds. The write is now blocked
73	    // upstream (isProtectedPath in lib/agent.ts); this is the second line, so
74	    // that a gap in the first one is not immediately catastrophic.
75	    //
76	    // Only what a build genuinely needs: a PATH to find node, the platform
77	    // variables Node itself requires on Windows, and NODE_ENV.
78	    const parent = process.env;
79	    const buildEnv: NodeJS.ProcessEnv = {
80	      NODE_ENV: "production",
81	      PATH: parent.PATH,
82	      // Windows resolves temp dirs and the system root through these; without
83	      // them the child fails in ways that look like a vite bug.
84	      ...(process.platform === "win32"
85	        ? {
86	            SystemRoot: parent.SystemRoot,
87	            windir: parent.windir,
88	            TEMP: parent.TEMP,
89	            TMP: parent.TMP,
90	            COMSPEC: parent.COMSPEC,
91	            PATHEXT: parent.PATHEXT,
92	          }
93	        : { HOME: parent.HOME }),
94	    };
95	
96	    const child = spawn(command, args, {
97	      cwd,
98	      timeout: BUILD_TIMEOUT_MS,
99	      env: buildEnv,
100	    });
101	
102	    let stderr = "";
103	    child.stderr?.on("data", (chunk) => {
104	      stderr += chunk.toString();
105	    });
106	
107	    child.on("error", (err) => reject(new BuildError(`Build could not start: ${err.message}`)));
108	
109	    child.on("close", (code, signal) => {
110	      if (signal === "SIGTERM") {
111	        reject(new BuildError("Build timed out."));
112	      } else if (code !== 0) {
113	        reject(new BuildError(`Build failed:\n${stderr.slice(-2000)}`));
114	      } else {
115	        resolve();
116	      }
117	    });
118	  });
119	}
120	
121	const TEXT_EXTENSIONS = new Set([".html", ".js", ".css", ".json", ".svg", ".txt", ".map"]);
122	
123	async function readDistTree(dir: string): Promise<FileMap> {
124	  const files: FileMap = {};
125	
126	  async function walk(current: string, prefix: string) {
127	    const entries = await readdir(current, { withFileTypes: true });
128	    for (const entry of entries) {
129	      const full = join(current, entry.name);
130	      const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
131	      if (entry.isDirectory()) {
132	        await walk(full, rel);
133	      } else {
134	        const ext = entry.name.slice(entry.name.lastIndexOf("."));
135	        if (!TEXT_EXTENSIONS.has(ext)) continue; // no binary assets — matches the inline-SVG/data-URI-only contract
136	        const size = (await stat(full)).size;
137	        if (size > 2_000_000) continue; // guard against something huge slipping through
138	        files[rel] = await readFile(full, "utf8");
139	      }
140	    }
141	  }
142	
143	  await walk(dir, "");
144	  return files;
145	}
