1	import { db } from "./db";
2	import { FOUNDATION_FILES } from "./foundation";
3	import { buildSite } from "./build-site";
4	
5	// ── Onboarding seed project ────────────────────────────────────────────────
6	// New signups land on an empty dashboard otherwise, which is a bad first
7	// impression for a tool whose entire pitch is "describe it, watch it build."
8	// This gives every new account one already-buildable project with a live
9	// preview from the very first screen, using the exact same Vite+React+TS+
10	// Tailwind foundation every project starts from (lib/foundation.ts) — not a
11	// special-cased demo, so there's nothing extra to keep in sync.
12	//
13	// This is free onboarding content, not a paid generation — it must never
14	// touch the credit ledger.
15	
16	function slugify(name: string): string {
17	  const base = name
18	    .toLowerCase()
19	    .replace(/[^a-z0-9]+/g, "-")
20	    .replace(/^-+|-+$/g, "")
21	    .slice(0, 40);
22	  return (base || "site") + "-" + Math.random().toString(36).slice(2, 7);
23	}
24	
25	const WELCOME_MESSAGE =
26	  "This is your starting foundation — a real React app, ready to build on. Describe the site you want in the chat below, like \"a landing page for a coffee shop called Roan Coffee, warm and cozy\", and I'll build it for real.";
27	
28	/**
29	 * Gives a brand-new account a real project with a working preview instead of
30	 * an empty dashboard. Free onboarding content — never charges credits.
31	 */
32	export async function createSeedProject(userId: string): Promise<string> {
33	  const project = await db.project.create({
34	    data: { userId, name: "My first site", slug: slugify("my-first-site") },
35	  });
36	
37	  await db.projectFile.createMany({
38	    data: Object.entries(FOUNDATION_FILES).map(([path, content]) => ({
39	      projectId: project.id,
40	      path,
41	      content,
42	      published: false,
43	      kind: "source",
44	    })),
45	  });
46	
47	  // Pre-build the foundation so the preview shows something real immediately
48	  // rather than "nothing built yet" on the very first screen a user sees.
49	  // If the build ever fails here (it shouldn't — it's the same fixed
50	  // foundation every time), just skip it silently: the preview falls back to
51	  // its own empty state, which is a fine floor, not worth failing signup over.
52	  try {
53	    const compiled = await buildSite(FOUNDATION_FILES);
54	    await db.projectFile.createMany({
55	      data: Object.entries(compiled).map(([path, content]) => ({
56	        projectId: project.id,
57	        path,
58	        content,
59	        published: false,
60	        kind: "build",
61	      })),
62	    });
63	  } catch (err) {
64	    console.error("[kodely] seed project pre-build failed (non-fatal)", err);
65	  }
66	
67	  await db.message.create({
68	    data: { projectId: project.id, role: "assistant", content: WELCOME_MESSAGE },
69	  });
70	
71	  return project.id;
72	}
73

