import http from "node:http";
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CSP =
  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";

const font = readFileSync(join(__dirname, "test.woff2"));

const html = `<!doctype html>
<html><head><meta charset="utf-8">
<style>
@font-face {
  font-family: "TestFont";
  src: url("/test.woff2") format("woff2");
  font-weight: 400;
}
body { font-family: "TestFont", sans-serif; font-size: 40px; }
</style>
</head><body id="target">Hello Fonts</body>
<script>
window.__result = { loaded: false, error: null };
document.fonts.load('40px "TestFont"').then((fonts) => {
  window.__result.loaded = fonts.length > 0 && document.fonts.check('40px "TestFont"');
}).catch((e) => { window.__result.error = String(e); });
</script>
</html>`;

const server = http.createServer((req, res) => {
  if (req.url === "/test.woff2") {
    res.writeHead(200, { "Content-Type": "font/woff2", "Content-Security-Policy": CSP });
    res.end(font);
    return;
  }
  res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Content-Security-Policy": CSP });
  res.end(html);
});

server.listen(5173, () => console.log("listening on 5173"));

