1	import { db } from "@/lib/db";
2	import { getCurrentUser } from "@/lib/auth";
3	import { runAgent, normalizePath, type FileMap } from "@/lib/agent";
4	import { buildSite, BuildError } from "@/lib/build-site";
5	import {
6	  chargeForBuild,
7	  costMicros,
8	  getBalance,
9	  getSpendCapStatus,
10	  settleBuild,
11	  sumUsage,
12	  type Usage,
13	} from "@/lib/credits";
14	import { checkGenerateRateLimit } from "@/lib/rate-limit";
15	import { track, EVENTS } from "@/lib/events";
16	import { classifyFollowUp } from "@/lib/feedback-intent";
17	import { FLAGS, isEnabled } from "@/lib/flags";
18	import { brandPromptFragment, parseStoredBrandKit } from "@/lib/brand-kit";
19	
20	export const dynamic = "force-dynamic";
21	export const maxDuration = 300;
22	
23	function sse(event: unknown) {
24	  return `data: ${JSON.stringify(event)}\n\n`;
25	}
26	
27	// A build that fails to compile even after one repair attempt gives up — this
28	// bounds the worst case to ~2x the cost of a normal generation, not unbounded.
29	const MAX_BUILD_ATTEMPTS = 2;
30	
31	/** The four token columns on Build, from a Usage. */
32	function usageColumns(u: Usage) {
33	  return {
34	    inputTokens: u.inputTokens,
35	    outputTokens: u.outputTokens,
36	    cacheReadTokens: u.cacheReadTokens,
37	    cacheWriteTokens: u.cacheWriteTokens,
38	  };
39	}
40	
41	export async function POST(req: Request) {
42	  const user = await getCurrentUser();
43	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
44	
45	  const body = (await req.json().catch(() => null)) as {
46	    projectId?: string;
47	    prompt?: string;
48	    image?: string;
49	    document?: string;
50	  } | null;
51	  const prompt = body?.prompt?.trim();
52	  if (!body?.projectId || !prompt) {
53	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
54	  }
55	
56	  // Only a data: URL (what the client-side downscale in PromptHero, or the
57	  // composer's own image/video-frame path, produces) is accepted — anything
58	  // else is silently dropped rather than passed on.
59	  const imageMatch = body.image?.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
60	  const image = imageMatch ? { mediaType: imageMatch[1], data: imageMatch[2] } : undefined;
61	
62	  // Same idea, for a directly-attached PDF (app/(portal)/dashboard/new's
63	  // Composer/attachment.ts). Real document input to the model — see
64	  // lib/agent.ts's message construction — not a file that ends up embedded
65	  // in the built site.
66	  const documentMatch = body.document?.match(/^data:application\/pdf;base64,(.+)$/);
67	  const document = documentMatch ? { data: documentMatch[1] } : undefined;
68	
69	  const project = await db.project.findFirst({
70	    where: { id: body.projectId, userId: user.id },
71	    include: { messages: { orderBy: { createdAt: "asc" } } },
72	  });
73	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
74	
75	  // ── Kill switch ──────────────────────────────────────────────────────────
76	  // Placed after the project lookup (so an unknown project still 404s, and the
77	  // switch never leaks the existence of someone else's project) and before
78	  // EVERY spend path below it: the balance read, the spend cap, the Build row,
79	  // the user Message row and the model call in runAgent. Refusing here writes
80	  // nothing at all and charges nothing at all.
81	  //
82	  // Its own status and its own words, deliberately. The two checks immediately
83	  // below both answer 402 and both talk about credits; reusing either would
84	  // tell the user they are out of money during an incident that has nothing to
85	  // do with their balance, and they would go and top up. 503 is the honest
86	  // code: the capability is temporarily withdrawn by us.
87	  //
88	  // Bucketed on user.id — stable per user, so a partial rollout (if this were
89	  // ever operated as one) cannot flip the same person between requests.
90	  if (!(await isEnabled(FLAGS.generation, user.id))) {
91	    return Response.json(
92	      {
93	        error:
94	          "Building is paused right now while we sort out a problem on our side. Nothing has been charged and your project is untouched — please try again in a few minutes.",
95	      },
96	      { status: 503 },
97	    );
98	  }
99	
100	  const balance = await getBalance(user.id);
101	  if (balance <= 0) {
102	    track(EVENTS.creditsExhausted, { userId: user.id, props: { projectId: project.id } });
103	    return Response.json(
104	      { error: "You're out of credits. Top up to keep building." },
105	      { status: 402 },
106	    );
107	  }
108	
109	  // The user's own ceiling, checked before anything is spent. Distinct from
110	  // running out of credits: they still HAVE the balance, they asked us not to
111	  // burn past this without them saying so. The message says exactly that, so
112	  // it never reads as a surprise limit we imposed.
113	  const cap = await getSpendCapStatus(user.id);
114	  if (cap.reached) {
115	    track(EVENTS.spendCapReached, {
116	      userId: user.id,
117	      props: { cap: cap.cap, spent: cap.spent, projectId: project.id },
118	    });
119	    return Response.json(
120	      {
121	        error: `You've hit your own spending cap of ${cap.cap} credits per 30 days (${cap.spent} used). Raise or remove it in Settings to keep building.`,
122	        spendCapReached: true,
123	      },
124	      { status: 402 },
125	    );
126	  }
127	
128	  const rateLimit = await checkGenerateRateLimit(user.id);
129	  if (!rateLimit.allowed) {
130	    return Response.json(
131	      { error: "You're generating too fast — take a short break and try again shortly." },
132	      { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
133	    );
134	  }
135	
136	  // The foundation means source files are never empty — "first build" is
137	  // instead "first real customization request" for this project.
138	  const kind = project.messages.length === 0 ? "create" : "edit";
139	
140	  const build = await db.build.create({
141	    data: { projectId: project.id, status: "RUNNING", model: "", prompt },
142	  });
143	
144	  track(EVENTS.buildStarted, {
145	    userId: user.id,
146	    props: {
147	      buildId: build.id,
148	      projectId: project.id,
149	      kind,
150	      hasImage: Boolean(image),
151	      hasDocument: Boolean(document),
152	      // Only meaningful on an edit — a first build has no prior output to be
153	      // reacting to. Left off `create` so followUpIntents() isn't diluted by
154	      // rows that were never follow-ups.
155	      ...(kind === "edit" ? { intent: classifyFollowUp(prompt) } : {}),
156	    },
157	  });
158	
159	  await db.message.create({
160	    data: { projectId: project.id, role: "user", content: prompt },
161	  });
162	
163	  // Aborted when the client disconnects (tab closed, network drop) — cancels
164	  // the in-flight Anthropic request instead of burning tokens for nobody.
165	  const abortController = new AbortController();
166	
167	  const encoder = new TextEncoder();
168	  const stream = new ReadableStream({
169	    async start(controller) {
170	      // A client disconnect races with our own sends: enqueue on a closed
171	      // controller throws "Controller is already closed", which used to be
172	      // caught as a generic failure and wrongly mark an otherwise-fine build
173	      // FAILED. There's nothing to do about a gone client — swallow it.
174	      const send = (event: unknown) => {
175	        try {
176	          controller.enqueue(encoder.encode(sse(event)));
177	        } catch {
178	          // client is gone
179	        }
180	      };
181	
182	      let filesWritten = 0;
183	      let succeeded = false;
184	      // 0 means it compiled first try. This is the raw material for the
185	      // green-build-first-try metric (see greenBuildRate in lib/events.ts),
186	      // which the roadmap treats as a gate but nothing measured before.
187	      // Declared out here so the catch below can record it too.
188	      let repairAttempts = 0;
189	      // Usage kept PER ATTEMPT, not as one accumulator. A single running total
190	      // cannot tell the customer's request apart from the model repairing its
191	      // own broken output, and rule 4 of the anti-bill-shock contract charges
192	      // only the former (see settleBuild in lib/credits.ts). The run's true
193	      // total is still recorded — it is just sumUsage(attemptUsage) now.
194	      const attemptUsage: Usage[] = [];
195	      let model = "";
196	      let lastReply = "";
197	      let lastProgress = "";
198	
199	      const readSourceFiles = async (): Promise<FileMap> => {
200	        const rows = await db.projectFile.findMany({
201	          where: { projectId: project.id, published: false, kind: "source" },
202	        });
203	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
204	      };
205	
206	      try {
207	        // The project's brand kit, prepended to the FIRST request only.
208	        //
209	        // The repair loop below reassigns `request` on purpose: a repair pass
210	        // is about a compile error, not about the brand, and re-sending the
211	        // kit there would pay for it twice for no benefit.
212	        //
213	        // Without this the kit still reaches the generated site — the palette
214	        // is spliced into src/index.css as a Tailwind @theme block and the logo
215	        // is a real component — but the builder is never TOLD about it, so it
216	        // has no reason to use either.
217	        const brandRow = await db.projectFile.findFirst({
218	          where: { projectId: project.id, path: "brand.json", kind: "brand", published: false },
219	          select: { content: true },
220	        });
221	        const brand = brandRow ? parseStoredBrandKit(brandRow.content) : null;
222	
223	        let request = brand ? `${brandPromptFragment(brand)}\n\n${prompt}` : prompt;
224	        let buildOutput: FileMap | null = null;
225	        let lastBuildError = "";
226	
227	        // Resolved ONCE, outside the retry loop, so a repair pass can never run
228	        // on a different engine than the attempt it is repairing.
229	        //
230	        // Only ever an upgrade: runAgent treats KODELY_ENGINE=sdk as an
231	        // absolute pin and ignores this, so the flag cannot revoke an
232	        // operator's deliberate choice to stay off the metered key. Bucketed on
233	        // user.id, not per build — splitting one person's builds across both
234	        // engines would contaminate any comparison between them.
235	        const engine = (await isEnabled(FLAGS.sdkEngine, user.id)) ? "sdk" : "api";
236	
237	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
238	          if (abortController.signal.aborted) break;
239	
240	          const attemptTotals: Usage = {
241	            inputTokens: 0,
242	            outputTokens: 0,
243	            cacheReadTokens: 0,
244	            cacheWriteTokens: 0,
245	          };
246	          attemptUsage.push(attemptTotals);
247	
248	          const generator = runAgent({
249	            engine,
250	            history: project.messages.map((m) => ({
251	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
252	              content: m.content,
253	            })),
254	            request,
255	            files: await readSourceFiles(),
256	            kind,
257	            // Only attached on the very first turn of a project — a repair
258	            // retry re-sends the same `request` text but should not attach
259	            // the image (or document) again mid-loop.
260	            image: attempt === 1 ? image : undefined,
261	            document: attempt === 1 ? document : undefined,
262	            signal: abortController.signal,
263	            onWrite: async (path, content) => {
264	              if (!normalizePath(path)) return false;
265	              await db.projectFile.upsert({
266	                where: {
267	                  projectId_path_published_kind: {
268	                    projectId: project.id,
269	                    path,
270	                    published: false,
271	                    kind: "source",
272	                  },
273	                },
274	                create: { projectId: project.id, path, content, published: false, kind: "source" },
275	                update: { content },
276	              });
277	              filesWritten++;
278	              return true;
279	            },
280	            onDelete: async (path) => {
281	              const { count } = await db.projectFile.deleteMany({
282	                where: { projectId: project.id, path, published: false, kind: "source" },
283	              });
284	              return count > 0;
285	            },
286	          });
287	
288	          for await (const event of generator) {
289	            if (event.type === "text") {
290	              lastReply += event.text;
291	              send(event);
292	            } else if (event.type === "file") {
293	              send(event);
294	            } else if (event.type === "status") {
295	              send(event);
296	            } else if (event.type === "progress") {
297	              // Collapse consecutive identical lines. A run of twelve Reads
298	              // narrates as one "Looking through the project" rather than
299	              // twelve, which would read as a stutter rather than progress.
300	              if (event.text !== lastProgress) {
301	                lastProgress = event.text;
302	                send(event);
303	              }
304	            } else if (event.type === "usage") {
305	              model = event.model;
306	              attemptTotals.inputTokens += event.inputTokens;
307	              attemptTotals.outputTokens += event.outputTokens;
308	              attemptTotals.cacheReadTokens += event.cacheReadTokens;
309	              attemptTotals.cacheWriteTokens += event.cacheWriteTokens;
310	            }
311	          }
312	
313	          if (abortController.signal.aborted) break;
314	
315	          try {
316	            send({ type: "progress", text: "Compiling the site" });
317	            buildOutput = await buildSite(await readSourceFiles());
318	            break; // compiled cleanly — done
319	          } catch (err) {
320	            lastBuildError = err instanceof BuildError ? err.message : String(err);
321	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
322	            repairAttempts++;
323	            // Clear the dedupe key: the repair pass legitimately repeats the
324	            // same lines, and suppressing them would look like a stall.
325	            lastProgress = "";
326	            send({ type: "status", text: "Build didn't compile — fixing it…" });
327	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
328	          }
329	        }
330	
331	        if (abortController.signal.aborted || !buildOutput) {
332	          // Loop ended without a successful build and without throwing —
333	          // only reachable via the abort path (see the `break` above).
334	        } else {
335	          succeeded = true;
336	
337	          // Replace the compiled tree with the new build output.
338	          await db.$transaction([
339	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
340	            ...(Object.keys(buildOutput).length > 0
341	              ? [
342	                  db.projectFile.createMany({
343	                    data: Object.entries(buildOutput).map(([path, content]) => ({
344	                      projectId: project.id,
345	                      path,
346	                      content,
347	                      published: false,
348	                      kind: "build",
349	                    })),
350	                  }),
351	                ]
352	              : []),
353	          ]);
354	
355	          // costMicros is the WHOLE run — every attempt, recorded as spent.
356	          // credits is only the customer's own attempt; a repair pass is our
357	          // mistake and our cost. See settleBuild in lib/credits.ts.
358	          const totals = sumUsage(attemptUsage);
359	          const settlement = settleBuild(model, attemptUsage);
360	          const { costMicros: micros, credits } = settlement;
361	          // A zero charge writes no ledger row. The ledger is a financial
362	          // record; an entry that moves nothing is noise in a statement a
363	          // customer may one day be reading to understand their bill.
364	          const remaining =
365	            credits > 0
366	              ? await chargeForBuild(user.id, build.id, credits)
367	              : await getBalance(user.id);
368	
369	          const sourceFiles = await readSourceFiles();
370	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
371	
372	          await db.build.update({
373	            where: { id: build.id },
374	            data: {
375	              status: "SUCCEEDED",
376	              model,
377	              endedAt: new Date(),
378	              ...usageColumns(totals),
379	              filesWritten,
380	              repairAttempts,
381	              costMicros: micros,
382	              creditsCharged: credits,
383	              filesSnapshot,
384	            },
385	          });
386	
387	          track(EVENTS.buildSucceeded, {
388	            userId: user.id,
389	            props: {
390	              buildId: build.id,
391	              projectId: project.id,
392	              kind,
393	              model,
394	              repairAttempts,
395	              filesWritten,
396	              credits,
397	              remaining,
398	              // What rule 4 cost us on this build. Separate from `credits` so
399	              // the absorbed total is measurable without re-deriving it from
400	              // costMicros in every query.
401	              waivedCredits: settlement.waivedCredits,
402	              waivedMicros: settlement.waivedMicros,
403	            },
404	          });
405	
406	          if (lastReply.trim()) {
407	            await db.message.create({
408	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
409	            });
410	          }
411	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
412	
413	          // buildId travels to the client so it can attach a rating to this
414	          // specific build (see app/api/feedback/route.ts).
415	          //
416	          // repairWaived/waivedCredits make rule 4 visible instead of a silent
417	          // internal policy. The user watched "Build didn't compile — fixing
418	          // it…" go past; without this the next thing they see is a charge and
419	          // no statement that the fixing part was free. Editor.tsx ignores
420	          // fields it does not know, so it is safe to send today and to render
421	          // whenever that component is updated.
422	          send({
423	            type: "done",
424	            credits,
425	            remaining,
426	            filesWritten,
427	            buildId: build.id,
428	            repairAttempts,
429	            repairWaived: settlement.repairWaived,
430	            waivedCredits: settlement.waivedCredits,
431	          });
432	        }
433	
434	        if (!succeeded) {
435	          const spent = sumUsage(attemptUsage);
436	          await db.build.update({
437	            where: { id: build.id },
438	            data: {
439	              status: "FAILED",
440	              endedAt: new Date(),
441	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
442	              filesWritten,
443	              repairAttempts,
444	              creditsCharged: 0,
445	              // Charged zero, but the tokens were still spent. Rule 3 says a
446	              // failed build is "recorded with its true cost and charged
447	              // ZERO"; the recording half was missing, so every failure showed
448	              // $0.0000 in /admin and the give-away figure on
449	              // /admin/analytics was understated by exactly the cost of every
450	              // build that never worked. Under rule 4 that matters more, not
451	              // less: a run that burned two attempts and still failed is the
452	              // most expensive thing we absorb.
453	              ...usageColumns(spent),
454	              costMicros: costMicros(model, spent),
455	              // Record the model on failure too, when we got far enough to
456	              // learn it. It used to be written only on success, so every
457	              // failed build had a blank Model column — which made it
458	              // impossible to attribute a spike in failures to a model change,
459	              // exactly when you most need to.
460	              ...(model ? { model } : {}),
461	            },
462	          });
463	
464	          track(EVENTS.buildFailed, {
465	            userId: user.id,
466	            props: {
467	              buildId: build.id,
468	              projectId: project.id,
469	              kind,
470	              repairAttempts,
471	              reason: abortController.signal.aborted ? "aborted" : "no_output",
472	            },
473	          });
474	        }
475	      } catch (error) {
476	        // A build that fails is never charged — that is the product promise,
477	        // so the ledger is deliberately untouched on this path.
478	        const message =
479	          error instanceof Error ? error.message : "The build failed unexpectedly.";
480	        console.error("[kodely] build failed", build.id, error);
481	
482	        // Same as the other failure path: charged zero, recorded honestly.
483	        const spent = sumUsage(attemptUsage);
484	
485	        await db.build.update({
486	          where: { id: build.id },
487	          data: {
488	            status: "FAILED",
489	            endedAt: new Date(),
490	            error: message.slice(0, 1000),
491	            filesWritten,
492	            repairAttempts,
493	            creditsCharged: 0,
494	            ...usageColumns(spent),
495	            costMicros: costMicros(model, spent),
496	            // See the note on the other failure path — a blank model makes a
497	            // failure impossible to attribute.
498	            ...(model ? { model } : {}),
499	          },
500	        });
501	
502	        track(EVENTS.buildFailed, {
503	          userId: user.id,
504	          props: {
505	            buildId: build.id,
506	            projectId: project.id,
507	            kind,
508	            repairAttempts,
509	            reason: "error",
510	          },
511	        });
512	
513	        send({ type: "error", message });
514	      } finally {
515	        try {
516	          controller.close();
517	        } catch {
518	          // already closed by the client disconnect path
519	        }
520	      }
521	    },
522	    cancel() {
