import { loadKodely } from "./loader.mjs";
import { createHash } from "node:crypto";

const { buildSite, FOUNDATION_FILES } = await loadKodely();

const fontPaths = Object.keys(FOUNDATION_FILES).filter((p) => p.endsWith(".woff2"));
console.log(`Foundation source has ${fontPaths.length} .woff2 files under public/fonts/.`);

// Add a page that actually references one of the fonts via @font-face, same
// shape the real agent would write, to prove the whole path end to end.
const files = {
  ...FOUNDATION_FILES,
  "src/index.css": `@import "tailwindcss";\n\n@font-face {\n  font-family: "Fraunces";\n  src: url("/fonts/fraunces-700.woff2") format("woff2");\n  font-weight: 700;\n  font-display: swap;\n}\n\n:root {\n  color-scheme: light dark;\n}\n`,
};

console.log("Running real buildSite()...");
const dist = await buildSite(files);

const distFontPaths = Object.keys(dist).filter((p) => p.endsWith(".woff2"));
console.log(`Build output (dist) has ${distFontPaths.length} .woff2 files:`, distFontPaths);

if (distFontPaths.length !== fontPaths.length) {
  throw new Error("Font count mismatch between source and dist output!");
}

// Verify round-trip integrity: decode the dist output's base64 and hash it
// against the original source file's base64-decoded bytes.
let allMatch = true;
for (const p of distFontPaths) {
  const distRel = p; // e.g. "fonts/fraunces-700.woff2"
  const srcPath = `public/${distRel}`;
  const srcBuf = Buffer.from(FOUNDATION_FILES[srcPath], "base64");
  const distBuf = Buffer.from(dist[p], "base64");
  const srcHash = createHash("sha256").update(srcBuf).digest("hex");
  const distHash = createHash("sha256").update(distBuf).digest("hex");
  const match = srcHash === distHash;
  if (!match) allMatch = false;
  console.log(`${match ? "OK  " : "FAIL"} ${p}  (${distBuf.length} bytes)  sha256 ${distHash.slice(0, 12)}`);
}

// Also confirm the CSS actually references the font path Vite would resolve.
const cssFile = Object.keys(dist).find((p) => p.endsWith(".css"));
const cssContains = cssFile && dist[cssFile].includes("fraunces-700");
console.log(`Built CSS references fraunces-700: ${cssContains ? "yes" : "no"} (${cssFile})`);

if (!allMatch || !cssContains) {
  console.error("VERIFICATION FAILED");
  process.exit(1);
}
console.log("VERIFICATION PASSED: fonts survive source -> vite build -> dist byte-for-byte, and the built CSS references the real path.");

import { loadKodely } from "./loader.mjs";
import http from "node:http";

const { buildSite, FOUNDATION_FILES } = await loadKodely();

const files = {
  ...FOUNDATION_FILES,
  "src/pages/Home.tsx": `export default function Home() {\n  return <h1 style={{ fontFamily: "Fraunces", fontSize: 48 }}>Hello Fraunces</h1>;\n}\n`,
  "src/index.css": `@import "tailwindcss";\n\n@font-face {\n  font-family: "Fraunces";\n  src: url("/fonts/fraunces-700.woff2") format("woff2");\n  font-weight: 700;\n  font-display: swap;\n}\n\n:root {\n  color-scheme: light dark;\n}\n`,
};

const dist = await buildSite(files);

// The exact SANDBOX_CSP from app/api/site/[slug]/[[...path]]/route.ts and
// app/api/preview/[id]/[[...path]]/route.ts (must stay identical between them).
const CSP =
  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";

const MIME = {
  html: "text/html; charset=utf-8",
  css: "text/css; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  woff2: "font/woff2",
};

const server = http.createServer((req, res) => {
  const p = req.url === "/" ? "index.html" : req.url.replace(/^\//, "");
  const content = dist[p];
  if (content === undefined) {
    res.writeHead(404);
    res.end("not found: " + p);
    return;
  }
  const ext = p.split(".").pop();
  const body = ext === "woff2" ? Buffer.from(content, "base64") : content;
  res.writeHead(200, { "Content-Type": MIME[ext] ?? "application/octet-stream", "Content-Security-Policy": CSP });
  res.end(body);
});

server.listen(5174, () => console.log("READY on 5174"));

